//package math_codet;

import java.io.InputStream;
import java.util.InputMismatchException;
import java.io.IOException;
import java.util.*;
 /******************************************
*    AUTHOR:         AMAN KUMAR SINGH        *
*    INSTITUITION:   KALYANI GOVERNMENT ENGINEERING COLLEGE  *
******************************************/
public class lets_do {
    public static void main(String[] args) throws java.lang.Exception{
        InputReader in=new InputReader(System.in);
        StringBuffer str=new StringBuffer();
        int n=in.nextInt();
        int b=in.nextInt();
        int[] arr1=new int[n];
        int i=0;
        for(i=0;i<n;i++){
            arr1[i]=in.nextInt();
        }
        int odd=0,even=0;
        int[] pf1=new int[n];
        int[] pf2=new int[n];
        int sum1=0,sum2=0;
        for(i=0;i<n;i++){
            if(arr1[i]%2==0)
                sum1++;
            else
                sum2++;
            pf1[i]=sum1;
            pf2[i]=sum2;
        }
        int prev=0;
        int[] arr=new int[n];
        int p=0;
        for(i=1;i<n-2;i+=2){
            int x,y;
            if(prev==0){
                x=pf1[i];
                y=pf2[i];
            }
            else{
                x=pf1[i]-pf1[prev];
                y=pf2[i]-pf2[prev];
            }
            if(x==y){
                arr[p]=Math.abs(arr1[i+1]-arr1[i]);
                p++;
            }
        }

        int[] val=new int[p];
        for(i=0;i<p;i++)
            val[i]=1;
        int K[][] = new int[p+1][b+1];
        for (i = 0; i <= p; i++)
        {
            for (int w = 0; w <= b; w++)
            {
                if (i==0 || w==0)
                    K[i][w] = 0;
                else if (arr[i-1] <= w)
                    K[i][w] = Math.max(val[i-1] + K[i-1][w-arr[i-1]],  K[i-1][w]);
                else
                    K[i][w] = K[i-1][w];
            }  
        }
        System.out.println(K[p][b]);
    }

    static class InputReader{
        private InputStream stream;
        private byte[] buf = new byte[1024];
        private int curChar;
        private int numChars;

        public InputReader(InputStream stream) {
            this.stream = stream;
        }

        public int read() {
            if (numChars == -1)
                throw new UnknownError();
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    throw new UnknownError();
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar++];
        }

        public int peek() {
            if (numChars == -1)
                return -1;
            if (curChar >= numChars) {
                curChar = 0;
                try {
                    numChars = stream.read(buf);
                } catch (IOException e) {
                    return -1;
                }
                if (numChars <= 0)
                    return -1;
            }
            return buf[curChar];
        }

        public void skip(int x) {
            while (x-- > 0)
                read();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

        public String nextString() {
            return next();
        }

        public String next() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            StringBuffer res = new StringBuffer();
            do {
                res.appendCodePoint(c);
                c = read();
            } while (!isSpaceChar(c));

            return res.toString();
        }

        public String nextLine() {
            StringBuffer buf = new StringBuffer();
            int c = read();
            while (c != '\n' && c != -1) {
                if (c != '\r')
                    buf.appendCodePoint(c);
                c = read();
            }
            return buf.toString();
        }

        public double nextDouble() {
            int c = read();
            while (isSpaceChar(c))
                c = read();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = read();
            }
            double res = 0;
            while (!isSpaceChar(c) && c != '.') {
                if (c == 'e' || c == 'E')
                    return res * Math.pow(10, nextInt());
                if (c < '0' || c > '9')
                    throw new InputMismatchException();
                res *= 10;
                res += c - '0';
                c = read();
            }
            if (c == '.') {
                c = read();
                double m = 1;
                while (!isSpaceChar(c)) {
                    if (c == 'e' || c == 'E')
                        return res * Math.pow(10, nextInt());
                    if (c < '0' || c > '9')
                        throw new InputMismatchException();
                    m /= 10;
                    res += (c - '0') * m;
                    c = read();
                }
            }
            return res * sgn;
        }

        public boolean hasNext() {
            int value;
            while (isSpaceChar(value = peek()) && value != -1)
                read();
            return value != -1;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
